/** Standalone, same-origin research workspace. All values from workspace data are HTML escaped. */
export function renderWorkspace(nonce: string, csrf: string): string {
  const n = nonce.replaceAll('&', '&amp;').replaceAll('"', '&quot;').replaceAll('<', '&lt;');
  const token = JSON.stringify(csrf).replaceAll('<', '\\u003c').replaceAll('>', '\\u003e').replaceAll('&', '\\u0026');
  const csrfAttr = csrf.replaceAll('&', '&amp;').replaceAll('\"', '&quot;').replaceAll('<', '&lt;');
  const script = CLIENT.replace('__CSRF__', token);
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><meta name="jev-csrf" content="${csrfAttr}"><title>Jev · Research workspace</title>
<script nonce="${n}" data-theme-init>${THEME_INIT}</script>
<style nonce="${n}">${CSS}${NAVIGATION_CSS}${AI_SETTINGS_CSS}${DRAFT_PROGRESS_CSS}${DATA_TOOLS_CSS}${THEME_CSS}${STUDY_SETUP_CSS}${ANSWER_LIST_CSS}</style></head><body>
<header class="topbar"><a class="wordmark" href="/" aria-label="Jev research workspace"><span class="glyph" aria-hidden="true">J</span><span>jev <i>/ research desk</i></span></a><div class="topbar-tools">${THEME_CONTROL}<button id="dataToolsPill" class="button data-pill" data-act="data-open" aria-haspopup="dialog" aria-controls="dataToolsDialog" disabled>Data</button><button id="aiSettingsPill" class="button ai-pill" data-act="ai-open" aria-haspopup="dialog" aria-controls="aiSettingsDialog"><span class="pulse" id="aiDot"></span><span id="aiLabel">AI · Connecting…</span></button></div></header>
<div id="workspaceError" role="alert" class="workspace-error" hidden></div><aside id="workspaceSync" class="workspace-sync" role="status" hidden><p id="workspaceSyncMessage"></p><div class="row"><button class="button small" data-act="data-open">Data tools</button><button class="button small" data-act="reload-saved">Reload saved workspace</button></div></aside><main id="app"><div class="loading" role="status">Opening your workspace…</div></main><dialog id="dataToolsDialog" class="auth-dialog data-dialog" aria-labelledby="dataToolsTitle" aria-describedby="dataToolsDescription"><button class="close-dialog" data-act="data-close" aria-label="Close data tools">×</button><h2 id="dataToolsTitle">Data</h2><p id="dataToolsDescription" class="subtle">Your saved work stays on this machine. These optional tools let you keep a copy of your draft or move it elsewhere.</p><div class="data-action"><div><h3>Export draft</h3><p>Copy all projects, cohorts and studies, including unsaved edits.</p></div><button class="button" data-act="export">Export JSON</button></div><div class="data-action"><div><h3>Import draft</h3><p>Load a previously exported file. Review it before saving.</p></div><button class="button" data-act="import-open">Import JSON</button></div><p class="subtle data-scope">Draft files do not include run history or account connections.</p></dialog><dialog id="aiSettingsDialog" class="auth-dialog ai-dialog" aria-labelledby="aiSettingsTitle"><button class="close-dialog" data-act="ai-close" aria-label="Close AI settings">×</button><h2 id="aiSettingsTitle">AI settings</h2><p class="subtle">Shared settings for every cohort and study.</p><div id="aiSettingsBody"></div></dialog><dialog id="authDialog" class="auth-dialog"><form data-form="auth"><button type="button" class="close-dialog" data-act="auth-close" aria-label="Close">×</button><div class="eyebrow">Account connection</div><h2>Connect TypeSafe</h2><p class="subtle">Your key is sent to TypeSafe for verification, then saved in the configured credential store. It is not included in a report.</p><div class="field"><label for="authKey">TypeSafe API key</label><input id="authKey" name="apiKey" type="password" autocomplete="off" required></div><div class="row"><button class="button primary" type="submit">Verify and save key</button></div></form></dialog><dialog id="exportDialog" class="auth-dialog"><button class="close-dialog" data-act="export-close" aria-label="Close export">×</button><h2>Export workspace</h2><p class="subtle">Save this file or copy the JSON to keep or transfer your current draft, including all projects, cohorts and studies.</p><textarea id="exportJson" aria-label="Workspace JSON" readonly rows="12"></textarea><a id="exportDownload" class="button primary" download="jev-workspace.json">Download JSON</a></dialog><dialog id="importDialog" class="auth-dialog"><button class="close-dialog" data-act="import-close" aria-label="Close import">×</button><h2>Import workspace</h2><p class="subtle">Paste exported workspace JSON or choose a file. Review and confirm before replacing your current draft.</p><textarea id="importJson" aria-label="Import workspace JSON" rows="12" placeholder="Paste workspace JSON"></textarea><div class="row"><label class="button file-label" for="importFile">Choose JSON file</label><input class="hidden-file" id="importFile" type="file" accept="application/json,.json"><button class="button primary" data-act="import-apply">Import draft</button></div></dialog><dialog id="reloadDialog" class="auth-dialog" aria-labelledby="reloadTitle" aria-describedby="reloadDescription"><h2 id="reloadTitle">Reload saved workspace?</h2><p id="reloadDescription">Reloading discards your unsaved browser edits. Keep editing to export your draft first, or replace it with the latest saved workspace.</p><div class="row"><button class="button" data-act="reload-saved-close" autofocus>Keep editing</button><button class="button primary" data-act="reload-saved-confirm">Reload saved workspace</button></div></dialog><dialog id="deleteCohortDialog" class="auth-dialog" aria-labelledby="deleteCohortTitle" aria-describedby="deleteCohortDescription deleteCohortUsage"><h2 id="deleteCohortTitle">Delete cohort?</h2><p id="deleteCohortDescription"></p><p id="deleteCohortUsage" class="subtle"></p><div class="row"><button class="button" data-act="delete-cohort-close" autofocus>Keep cohort</button><button class="button danger" data-act="delete-cohort-confirm">Delete from draft</button></div></dialog>${ANSWER_LIST_DIALOG}<div id="toast" class="toast" role="status" aria-live="polite"></div>
<script nonce="${n}">${script}</script></body></html>`;
}

