function proposalChanges(before,after){const sections=[{kind:'cohort',key:'cohorts',children:'personas',childLabel:'personas'},{kind:'study',key:'pipelines',children:'stages',childLabel:'phases'}];const summaries=[],items=[];let removals=0;for(const section of sections){const old=before[section.key],next=after[section.key],oldById=new Map(old.map(x=>[x.id,x])),nextById=new Map(next.map(x=>[x.id,x]));const added=next.filter(x=>!oldById.has(x.id)),removed=old.filter(x=>!nextById.has(x.id)),changed=next.filter(x=>oldById.has(x.id)&&JSON.stringify(x)!==JSON.stringify(oldById.get(x.id)));summaries.push((section.kind==='cohort'?'Cohorts':'Studies')+': '+added.length+' added · '+changed.length+' changed · '+removed.length+' removed');for(const x of added)items.push('<li>Added '+section.kind+': <strong>'+esc(x.name)+'</strong> <code>('+esc(x.id)+')</code> · '+x[section.children].length+' '+section.childLabel+'</li>');for(const x of changed){const previous=oldById.get(x.id),addedChildren=x[section.children].filter(child=>!previous[section.children].some(oldChild=>oldChild.id===child.id)).length,removedChildren=previous[section.children].filter(child=>!x[section.children].some(newChild=>newChild.id===child.id)).length;removals+=removedChildren;items.push('<li>Changed '+section.kind+': <strong>'+esc(previous.name)+(previous.name!==x.name?' → '+esc(x.name):'')+'</strong> <code>('+esc(x.id)+')</code>'+((addedChildren||removedChildren)?' · '+addedChildren+' '+section.childLabel+' added · '+removedChildren+' '+section.childLabel+' removed':'')+'</li>')}for(const x of removed){removals+=1+x[section.children].length;items.push('<li>Removed '+section.kind+': <strong>'+esc(x.name)+'</strong> <code>('+esc(x.id)+')</code> · '+x[section.children].length+' '+section.childLabel+' removed</li>')}}return '<div class="'+(removals?'warning':'notice')+'">'+summaries.map(esc).join('<br>')+(removals?'<br>Applying replaces the saved workspace, including the removals listed below.':'')+'</div>'+(items.length?'<ul class="proposal-items">'+items.join('')+'</ul>':'<p class="subtle">No workspace changes.</p>')}
function proposalReview(job){if(!job)return '';if(job.persona)return '<div class="notice">Individual persona task. <button class="button" data-act="persona-job-open">Review persona replacement</button></div>';if(job.cohort)return cohortProposalReview(job);if(job.status==='running')return draftProgress(job);if(job.status!=='completed'||!job.proposal)return panel(job.status==='cancelled'?'Preparation cancelled':'Preparation failed','', '<div class="warning">'+esc(job.message||'No proposal was returned.')+'</div>');const draft=job.proposal.document,before=workspaceCounts(S.doc),after=workspaceCounts(draft),stale=job.revision!==S.revision;return panel(S.proposalApplied?'Proposal applied':'Review proposed changes','Applying saves the new workspace. It does not start a poll.','<p>'+esc(job.proposal.explanation)+'</p><div class="proposal-diff"><div><span class="section-kicker">Virtual cohorts</span><strong>'+before.pools+' → '+after.pools+'</strong><span>'+before.personas+' → '+after.personas+' personas</span></div><div><span class="section-kicker">Studies</span><strong>'+before.pipelines+' → '+after.pipelines+'</strong><span>'+before.phases+' → '+after.phases+' phases</span></div></div>'+proposalChanges(S.doc,draft)+'<details class="advanced" data-detail-key="proposal-json"><summary>Inspect complete proposed workspace</summary><textarea class="agent-code" aria-label="Proposed workspace JSON" readonly rows="16">'+esc(JSON.stringify(draft,null,2))+'</textarea></details>'+(S.proposalApplied?'<div class="toolbar"><button class="button primary" data-act="tab" data-tab="cohorts">Open cohorts</button><button class="button" data-act="tab" data-tab="studies">Open studies</button></div>':(stale?'<div class="warning">Workspace changed since this proposal began. Prepare a new proposal against the latest saved draft.</div>':'')+'<div class="toolbar"><button class="button primary" data-act="assistant-apply" '+(stale||S.dirty||S.remoteRevision!==null||S.localLoading?'disabled':'')+'>Apply proposal</button><button class="button" data-act="assistant-discard">Discard proposal</button></div>'))}
function agents(){const active=S.localStart||S.localJob,running=active?.status==='running';const drafting=panel('Describe what you want to build','Use your ChatGPT subscription or an installed Codex or Claude CLI.','<form data-form="assistant"><fieldset '+(running?'disabled':'')+' style="border:0;padding:0;margin:0;min-width:0">'+'<div class="field"><label for="assistantPrompt">Your request</label><textarea id="assistantPrompt" name="localPrompt" class="assistant-prompt" rows="6" placeholder="Describe the people in your cohort, the question to answer, and how later phases should use the result.">'+esc(S.localPrompt)+'</textarea></div><p class="assistant-scope">Uses your current project edits and your request. Include the facts or sources you want used. Generated profile details are assumptions; this drafting step does not browse the web.</p>'+'</fieldset><div class="row generation-actions"><button class="button primary" data-act="assistant-generate" type="button" '+(!draftReady()||!S.localPrompt.trim()||S.remoteRevision!==null||running||S.localLoading?'disabled':'')+'>'+(running?'Preparing proposal…':'Prepare proposal')+'</button>'+draftCancelButton(active)+'</div></form>'+(S.localError?'<div class="warning" role="alert">'+esc(S.localError)+'</div>':''));const content=sectionPanels('assistant',[{id:'draft',label:'Request',html:drafting},{id:'proposal',label:running?'Progress':'Proposal',html:proposalReview(active)||empty('No proposal yet','Describe your request first.')}]);return header('Local assistant','Describe your cohort or study. Review a proposal before applying it.','<button class="button" data-act="refresh">Refresh workspace</button>')+tabs()+'<section id="view-agents" role="tabpanel" aria-labelledby="tab-agents"><div class="layout"><div class="maincol">'+content+'</div><aside class="aside"><div class="mini-card"><span class="section-kicker">Two kinds of AI</span><h3>Your agent prepares. Jev evaluates.</h3><ol class="agent-steps"><li>Your selected provider drafts cohorts, personas, and connected phases.</li><li>You inspect and apply its proposal.</li><li>Each Jev evaluates a persona when you explicitly run the study.</li></ol></div><div class="mini-card"><h3>Same workspace</h3><p>Manual edits and applied proposals share the same saved cohorts and studies. Unsaved changes stay protected.</p></div><div class="mini-card"><h3>Your existing sign-in</h3><p>Drafting uses your ChatGPT plan connection or the selected CLI and its existing account. TypeSafe credentials stay with the polling server.</p></div></aside></div></section>'}
async function loadLocalAgents(){if(S.localLoading)return;let recovered=false;S.localLoading=true;S.localError=null;try{const result=await api('/api/local-agents');S.localEngines=result.engines;void loadChatGpt();if(!S.localEngines.some(e=>e.id===S.localEngine))S.localEngine=S.localEngines.find(e=>e.available)?.id||S.localEngines[0]?.id||'codex';if(S.projectId&&!S.localJob){let previous;try{previous=sessionStorage.getItem('jev-local-job:'+location.origin+':'+S.projectId)}catch{}if(previous){try{S.localJob=await api('/api/agent/jobs/'+encodeURIComponent(previous));recovered=true;if(S.localJob.projectId&&S.localJob.projectId!==S.projectId){S.localJob=null;return}if(S.localJob.persona){S.cohortId=S.localJob.persona.cohortId;S.personId=S.localJob.persona.personaId;S.personaOpen=true;S.personaRegenOpen=true;}if(S.localJob.cohort){S.cohortTarget=S.localJob.cohort.id;S.cohortPrompt=S.localJob.cohort.prompt;S.cohortSize=S.localJob.cohort.size;S.cohortLastSize=S.cohortSize;S.cohortComposer=true;S.sections['cohort-generation']='review'}if(S.localJob.status==='running')void pollLocalJob(previous)}catch{}}}}catch(error){S.localError=error instanceof Error?error.message:String(error)}finally{S.localLoading=false;if(recovered&&showingLocalJob())render();else{updateAISettings();updateDraftReadiness()}}}
function rememberLocalJob(id){try{if(id)sessionStorage.setItem('jev-local-job:'+location.origin+':'+S.projectId,id);else sessionStorage.removeItem('jev-local-job:'+location.origin+':'+S.projectId)}catch{}}
async function startLocalJob(){if(!project())throw Error('Open a project first.');if(S.localStarting||S.localJob?.status==='running'||S.localLoading)return;const prompt=S.localPrompt.trim();if(!prompt)throw Error('Describe the cohort or study you want.');if(!draftReady())throw Error('Choose an available drafting provider and a ChatGPT model in AI settings.');await startDraftJob(()=>{S.sections.assistant='proposal';return {prompt}})}
async function startDraftJob(details){
  if(S.localStarting||S.localLoading||S.localJob?.status==='running')return;
  if(S.remoteRevision!==null)throw Error('Workspace changed. Reload the saved workspace before generating.');
  flushForms();
  const request={projectId:S.projectId,engine:S.localEngine,...(S.localEngine==='chatgpt'?{model:S.chatgptModel}:{}),...details()};
  S.localStarting=true;S.localLoading=true;S.localError=null;S.localPollError=null;S.proposalApplied=false;
  S.localStart={...request,status:'running',startedAt:new Date().toISOString(),progress:{phase:S.dirty?'saving':'checking',...(request.cohort?{completedPersonas:0,totalPersonas:request.cohort.size}:request.persona?{completedPersonas:0,totalPersonas:1}:{})}};render();
  try{await save({throwOnError:true});S.localStart.progress.phase='checking';render();S.localJob=await api('/api/agent/jobs','POST',{...request,revision:S.revision});rememberLocalJob(S.localJob.id);if(S.localJob.status==='running')void pollLocalJob(S.localJob.id)}
  catch(error){S.localError=error instanceof Error?error.message:String(error);if(request.cohort)S.sections['cohort-generation']='prompt';else if(!request.persona)S.sections.assistant='draft'}
  finally{S.localLoading=false;S.localStarting=false;S.localStart=null;render()}
}

async function pollLocalJob(jobId){if(localPolls.has(jobId))return;localPolls.add(jobId);try{while(S.localJob?.id===jobId&&S.localJob.status==='running'){await new Promise(resolve=>setTimeout(resolve,1000));if(S.localJob?.id!==jobId||S.localJob.status!=='running')break;const job=await api('/api/agent/jobs/'+encodeURIComponent(jobId));if(S.localJob?.id!==jobId||S.localJob.status!=='running')break;const changed=!!S.localPollError||JSON.stringify(job)!==JSON.stringify(S.localJob);S.localJob=job;S.localPollError=null;if(changed&&showingLocalJob())render()}}catch(error){if(S.localJob?.id===jobId&&S.localJob.status==='running'){S.localPollError=error instanceof Error?error.message:String(error);if(showingLocalJob())render()}}finally{localPolls.delete(jobId)}}
async function cancelLocalJob(){const jobId=S.localJob?.id;if(S.localJob?.status!=='running')return;const job=await api('/api/agent/jobs/'+encodeURIComponent(jobId)+'/cancel','POST',{});if(S.localJob?.id===jobId){S.localJob=job;S.localPollError=null;if(showingLocalJob())render()}}
async function applyLocalProposal(){const job=S.localJob;if(job?.projectId&&job.projectId!==S.projectId)throw Error('Open the project that generated this draft.');if(!job?.proposal||job.status!=='completed'||S.proposalApplied)return;if(S.dirty||S.revision!==job.revision)throw Error('Workspace changed. Save your edits and prepare a new proposal.');S.localLoading=true;S.loading=true;root.inert=true;try{const saved=await api('/api/agent/jobs/'+encodeURIComponent(job.id)+'/apply','POST',{revision:S.revision});S.proposalApplied=true;applySnapshot({...S.snap,...saved},true);rememberLocalJob(null);say('Proposal applied. Configure your cohorts or review the study.')}finally{S.localLoading=false;S.loading=false;root.inert=false;render()}}
async function loadAgentConfig(){if(S.agentLoading)return;S.agentLoading=true;S.agentError=null;updateAISettings();try{S.agentConfig=await api('/api/agent-config')}catch(error){S.agentError=error instanceof Error?error.message:String(error)}finally{S.agentLoading=false;updateAISettings()}}
async function copyAgentText(target){const field=document.getElementById(target);if(!field)return;try{if(!navigator.clipboard?.writeText)throw Error('Clipboard unavailable');await navigator.clipboard.writeText(field.value);say('Copied.')}catch{field.focus();field.select();say('Text selected. Press Copy in your browser or use your keyboard shortcut.')}}
function updateAuth(){updateAIPill();updateEvaluationControls();document.getElementById('dataToolsPill').disabled=!S.doc||S.loading||S.localStarting}
function closeDataTools(){const dialog=document.getElementById('dataToolsDialog');if(dialog.open){dialog.close();document.getElementById('dataToolsPill').focus()}}
function updateSyncNotice(){const box=document.getElementById('workspaceSync');box.hidden=S.remoteRevision===null;if(!box.hidden)document.getElementById('workspaceSyncMessage').textContent='Saved workspace changed in another agent or tab. Your unsaved edits are still here. Export your draft before reloading saved revision '+S.remoteRevision+'.'}
function retainSelections(){if(!project())S.projectId=null;const p=pipeline(),c=cohort();if(!p){S.pipelineId=null;S.stageId=null}else if(!p.stages.some(stage=>stage.id===S.stageId))S.stageId=p.stages[0]?.id||null;if(!c){S.cohortId=null;S.personId=null}else if(!c.personas.some(persona=>persona.id===S.personId))S.personId=null}
