function render(){if(S.flushing)return;const focusedProgress=document.activeElement?.closest?.('.draft-progress')?document.activeElement?.dataset:null;const disclosures=new Map([...root.querySelectorAll('details[data-detail-key]')].map(node=>[node.dataset.detailKey,node.open]));if(!S.snap){root.innerHTML='<div class="loading" role="status">Opening your workspace…</div>';return}updateAuth();updateSyncNotice();let html=!project()?projects():S.tab==='project-settings'?projectSettings():S.tab==='cohorts'?cohorts():S.tab==='runs'?runs():S.tab==='agents'?agents():S.plan?review():studies();root.innerHTML='<div class="shell">'+(project()?projectNavigation():'')+html+'</div>';root.querySelectorAll('details[data-detail-key]').forEach(node=>{if(disclosures.has(node.dataset.detailKey))node.open=disclosures.get(node.dataset.detailKey)});root.classList.toggle('busy',S.loading);root.inert=S.loading||S.localStarting;wireTabKeys();drawStageEdges();if(focusedProgress?.act==='assistant-cancel')root.querySelector('[data-act=assistant-cancel]')?.focus();else if(focusedProgress?.act==='draft-progress-section')root.querySelector('[data-act=draft-progress-section][data-section="'+(focusedProgress.section==='checks'?'checks':'activity')+'"]')?.focus()}
