function backgroundSync(){if(document.visibilityState==='visible')refresh().catch(()=>{})}
function fail(error){const box=document.getElementById('workspaceError');box.textContent=error instanceof Error?error.message:String(error);box.hidden=false}
function clearError(){document.getElementById('workspaceError').hidden=true}
function flushForms(skipForm){if(!S.dirty)return;const before=clone(S.doc),personId=S.personId,segmentId=S.segmentId;const sourceRenames=new Map([...root.querySelectorAll('[data-form=source]')].map(f=>[f.dataset.id,f.querySelector('[name=sourceId]').value]));const segmentRenames=new Map([...root.querySelectorAll('[data-form=segment]')].map(f=>[f.dataset.id,f.querySelector('[name=segmentId]').value]));S.formError=null;S.flushing=true;try{for(const form of root.querySelectorAll('[data-form]'))if(form!==skipForm&&!['auth','run-options','new-project','new-pipeline','assistant','cohort-generator','distribution-target','persona-regeneration'].includes(form.dataset.form)){if(!form.reportValidity())throw Error('Complete the invalid fields before saving or leaving this editor.');form.requestSubmit();if(S.formError)throw Error(S.formError)}const c=cohort();if(S.tab==='cohorts'&&c){[...c.personas,...c.segments].forEach(x=>x.sourceIds=x.sourceIds.map(id=>sourceRenames.get(id)||id));c.personas.forEach(x=>x.segment=segmentRenames.get(x.segment)||x.segment)}}catch(error){S.doc=before;S.personId=personId;S.segmentId=segmentId;throw error}finally{S.flushing=false}}
async function save({throwOnError=false}={}){if(!S.dirty)return;let requestStarted=false;try{flushForms();requestStarted=true;S.loading=true;render();const saved=await api('/api/workspace','POST',{document:S.doc,revision:S.revision});S.revision=saved.revision;S.doc=clone(saved.document);S.snap.document=S.doc;S.snap.revision=S.revision;S.remoteRevision=null;S.dirty=false;updateSyncNotice();say('Draft saved.')}catch(error){if(throwOnError)throw error;fail(error)}finally{S.loading=false;if(requestStarted)render()}}
async function reviewPlan(){flushForms();validateSetupAnswers(pipeline());if(S.dirty)await save({throwOnError:true});const projectId=S.projectId,pipelineId=S.pipelineId,revision=S.revision,provider=S.evaluationProvider;const plan=await api('/api/plan','POST',{projectId,pipelineId,provider});if(S.projectId!==projectId||S.pipelineId!==pipelineId||S.revision!==revision||S.evaluationProvider!==provider||S.dirty)return;S.plan=plan;S.seed=String(Date.now());S.maxRequests=Math.max(1,S.plan.maxRequests);render()}
async function beginRun(){const form=root.querySelector('[data-form=run-options]');if(form){const d=new FormData(form);S.seed=String(d.get('seed')||S.seed);S.concurrency=Number(d.get('concurrency'))||4;S.maxRequests=Number(d.get('maxRequests'))||100}S.loading=true;root.inert=true;let result;try{result=await api('/api/run','POST',{projectId:S.projectId,pipelineId:S.pipelineId,provider:S.plan.provider||'typesafe',revision:S.plan.revision,planToken:S.plan.planToken,seed:S.seed,concurrency:S.concurrency,maxRequests:S.maxRequests})}finally{S.loading=false;root.inert=false}S.plan=null;S.tab='runs';await refresh();say('Run started. Progress will update here.');render();pollRun(result.id)}
async function pollRun(runId){while(true){await new Promise(r=>setTimeout(r,900));try{const run=await api('/api/run/'+encodeURIComponent(runId));const ix=S.snap.runs.findIndex(x=>x.id===run.id);if(ix>=0)S.snap.runs[ix]=run;else S.snap.runs.unshift(run);S.snap.activeRun=run.status==='running'?run:null;if(S.tab==='runs')render();if(run.status!=='running')return}catch(e){say(e.message);return}}}
