function addNextPhase(){const p=pipeline();if(!p)return;const previous=selectedStage()||p.stages.at(-1),output=previous?phaseOutput(p,previous)[0]:null,phase={id:id(),label:'Next question',kind:'poll',cohort:previous?.kind==='poll'?previous.cohort:Object.keys(p.cohorts)[0]||'',questions:{answer:{type:'choice',label:'What should this phase decide?',instructions:'Use your persona and the provided inputs to answer the question.',criteria:{option_a:'',option_b:''}}},dependsOn:previous?[previous.id]:[],inputs:previous&&output?{previous_result:{stage:previous.id,question:output.id,select:'summary'}}:{},repeats:1};p.stages.push(phase);S.stageId=phase.id;S.sections.pipeline='phase';S.dirty=true;S.plan=null;render()}
