document.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();if(S.loading||S.localStarting&&!S.flushing)return;if(form.dataset.form==='new-project'){createProject(form).catch(fail);return}if(form.dataset.form==='distribution-target'){explorerAction('target-apply',{dataset:{}});return}if(form.dataset.form==='persona-regeneration'){startPersonaJob().catch(fail);return}if(form.dataset.form==='cohort-generator'){startCohortJob().catch(fail);return}if(form.dataset.form==='assistant'){startLocalJob().catch(fail);return}if(!S.flushing&&!['auth','new-pipeline'].includes(form.dataset.form)){try{if(form.dataset.form==='segment-shares')applySegmentShares(clone(cohort()),form);flushForms(form);clearError()}catch(error){S.formError=error instanceof Error?error.message:'Check the fields and try again.';fail(error);return}}try{const kind=form.dataset.form,d=new FormData(form);if(kind==='segment-shares'){applySegmentShares(cohort(),form);S.dirty=true;S.plan=null;render()}else if(kind==='project-settings'){const p=project();p.name=String(d.get('name')||'').trim();if(!p.name)throw Error('Name your project first.');p.description=String(d.get('description')||'');S.dirty=true;render()}else if(kind==='new-pipeline'){const q=String(d.get('question')||'').trim();if(!q)throw Error('Write the decision question first.');const p=freshPipeline(q);S.newQuestion='';if(projectPipelines().length)throw Error("This project already has a study. Open it to add phases.");S.doc.pipelines.push(p);ownPipeline(p);S.pipelineId=p.id;S.stageId=p.stages[0].id;S.sections.pipeline='phase';S.sections['phase-'+S.stageId]='question';S.dirty=true;render()}else if(kind==='pipeline'){const p=pipeline();p.name=String(d.get('name')||'Untitled study');p.description=String(d.get('description')||'');p.context=jparse(String(d.get('context')||'{}'),{});const alias=String(d.get('cohortAlias')||'').trim(),cohortId=String(d.get('cohortId')||'');if(alias&&cohortId)p.cohorts[alias]=cohortId;S.dirty=true;S.plan=null;render()}else if(kind==='study-setup'){applyStudySetup(form);render()}else if(kind==='stage')applyStage(form);else if(kind==='cohort'){const c=cohort();c.name=String(d.get('name')||'Untitled cohort');c.population=String(d.get('population')||'');c.description=String(d.get('description')||'');const brief=String(d.get('generationPrompt')||'').trim();if(brief)c.generationPrompt=brief;else delete c.generationPrompt;c.assumptions=parseLines(String(d.get('assumptions')||''));S.dirty=true;render()}else if(kind==='source'){const c=cohort(),x=c.sources.find(v=>v.id===form.dataset.id);const oldId=x.id;x.id=String(d.get('sourceId')||x.id);if(x.id!==oldId){c.segments.forEach(v=>v.sourceIds=v.sourceIds.map(z=>z===oldId?x.id:z));c.personas.forEach(v=>v.sourceIds=v.sourceIds.map(z=>z===oldId?x.id:z))}x.title=String(d.get('sourceTitle')||'');x.url=String(d.get('sourceUrl')||'');const date=String(d.get('retrievedAt')||'');x.retrievedAt=date?(date.includes('T')?date:new Date(date+'T00:00:00.000Z').toISOString()):'';x.notes=String(d.get('sourceNotes')||'');S.dirty=true;render()}else if(kind==='segment'){const c=cohort(),x=c.segments.find(v=>v.id===form.dataset.id);const oldId=x.id;x.id=String(d.get('segmentId')||x.id);if(x.id!==oldId){c.personas.forEach(v=>{if(v.segment===oldId)v.segment=x.id});(c.distributionTargets||[]).filter(t=>t.field==='segment').forEach(t=>t.buckets.forEach(b=>{if(b.value===oldId)b.value=x.id}))}x.label=String(d.get('segmentLabel')||'');x.description=String(d.get('segmentDescription')||'');if(d.get('segmentWeight')!==null)x.weight=Math.max(0,Number(d.get('segmentWeight'))||0);S.segmentId=x.id;if(form.dataset.weightBasis===undefined||String(d.get('weightBasis'))!==form.dataset.weightBasis)x.weightBasis=String(d.get('weightBasis')||'assumed');x.sourceIds=d.getAll('sourceIds').map(String);S.dirty=true;render()}else if(kind==='auth'){const key=form.querySelector('[name=apiKey]'),apiKey=key.value;key.value='';const submit=form.querySelector('[type=submit]');submit.disabled=true;api('/api/auth','POST',{apiKey}).then(result=>{S.snap.auth=result.auth;document.getElementById('authDialog').close();say('TypeSafe connected.');updateAISettings()}).catch(fail).finally(()=>{submit.disabled=false})}else if(kind==='persona-weight'){const p=cohort().personas.find(x=>x.id===S.personId),weight=Number(d.get('relativeWeight'));if(!Number.isFinite(weight)||weight<=0)throw Error('Persona weight must be greater than zero.');p.weight=weight;S.dirty=true;S.plan=null;render()}else if(kind==='persona'){const c=cohort(),p=c.personas.find(x=>x.id===S.personId);p.id=String(d.get('personaId')||p.id);S.personId=p.id;p.label=String(d.get('personaLabel')||'Synthetic profile');p.age=Math.max(18,Number(d.get('age'))||18);p.segment=String(d.get('segment')||'');p.background=String(d.get('background')||'');p.attributes=jparse(String(d.get('attributes')||'{}'),{});p.syntheticFields=parseLines(String(d.get('syntheticFields')||''));p.sourceIds=d.getAll('sourceIds').map(String);S.dirty=true;render()} }catch(err){S.formError=err instanceof Error?err.message:'Check the fields and try again.';fail(S.formError)}});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='answerListFile'){await readAnswerListFile(el.files?.[0]);return}if(answerListDraft&&['answerListColumn','answerListHeader'].includes(el.id)){answerListDraft.column=Number(document.getElementById('answerListColumn').value);answerListDraft.header=document.getElementById('answerListHeader').checked;answerListDraft.page=0;updateAnswerList();return}if(S.loading||S.localStarting)return;if(el.name==='listPage'){try{if(!el.closest('[data-form=segment-shares]'))flushForms();navigationAction('page-action',{dataset:{pageKey:el.dataset.pageKey,page:el.value},closest:selector=>el.closest(selector)})}catch(error){fail(error)}return}if(el.name==='phasePool'){try{flushForms();clearError();render();root.querySelector('[name=phasePool]')?.focus()}catch(error){fail(error)}return}if(el.name==='phasePicker'){try{flushForms();S.stageId=el.value;S.sections['phase-'+S.stageId]=selectedStage()?.kind==='poll'?'question':'inputs';render()}catch(error){fail(error)}return}if(el.name==='personaGroup'){flushForms();S.personaGroup=el.value;S.personaPage=0;S.listPages[S.projectId+':personas']=0;render();return}if(el.name==='distributionField'){S.distributionField=el.value;S.listPages[S.projectId+':distribution-buckets']=0;S.targetDraft=null;render();return}if(el.name==='distributionMeasure'){S.distributionWeighted=el.value==='weighted';render();return}if(el.name==='targetKind'){readTargetForm();S.targetDraft.buckets=el.value==='numeric'?[{label:'Range',min:18,max:121,percent:100}]:[{label:'Group A',value:'Group A',percent:100}];render();return}if(el.name==='chatgptModel'){S.chatgptCustomModel=el.value==='__custom__';S.chatgptModel=S.chatgptCustomModel?'':el.value;rememberAISelection();updateAISettings();updateDraftReadiness();return}if(el.name==='cohortSize'){cohortCountInput(el,true);return}if(el.name==='chatgptCustomModelId')return;if(el.name==='chatgptAccount'){changeChatGpt('select',el.value).catch(fail);return}if(el.name==='evaluationProvider'){const hadPlan=!!S.plan;S.evaluationProvider=el.value;S.plan=null;try{localStorage.setItem('jev-evaluation-provider',el.value)}catch{}if(hadPlan)render();updateAISettings();return}if(el.name==='localEngine'){S.localEngine=el.value;rememberAISelection();updateAISettings();updateDraftReadiness();return}if(el.name==='agentClient'){S.agentClient=el.value;updateAISettings();return}if(el.id!=='importFile'&&!el.matches('[data-cond-kind]')&&el.name!=='hasWhen'&&el.name!=='questionType'&&el.name!=='fromStage'&&!/^inputStage/.test(el.name)&&!/^binding(Stage|Question)/.test(el.name)&&el.dataset.condField!=='stage')return;try{clearError();if(el.id!=='importFile')flushForms();if(el.matches('[data-cond-kind]')){const s=selectedStage(),path=el.dataset.condKind,node=conditionAt(s,path),kind=el.value;if(kind==='leaf'){const leaf=clone(node.not||node.all?.[0]||node.any?.[0]||freshCondition(pipeline(),s));Object.keys(node).forEach(k=>delete node[k]);Object.assign(node,leaf)}else if(kind==='not'){const old=clone(node.not||node.all?.[0]||node.any?.[0]||node);Object.keys(node).forEach(k=>delete node[k]);node.not=old}else{const old=clone(node.not||node.all?.[0]||node.any?.[0]||node);Object.keys(node).forEach(k=>delete node[k]);node[kind]=[old,freshCondition(pipeline(),s)]}S.dirty=true;S.plan=null;render();return}if(el.name==='hasWhen'){const s=selectedStage();if(s){if(el.checked)s.when=s.when||freshCondition(pipeline(),s);else delete s.when;S.dirty=true;render()}return}if(el.id==='importFile'&&el.files?.[0]){document.getElementById('importJson').value=await el.files[0].text();el.value=''}else if(el.name==='questionType'||el.name==='fromStage'||/^inputStage/.test(el.name)||/^binding(Stage|Question)/.test(el.name)||el.dataset.condField==='stage'){const s=selectedStage(),p=pipeline();if(/^bindingStage/.test(el.name)){const input=Object.values(s.inputs)[Number(el.name.slice(12))];input.question=questionOptions(p,input.stage)[0]?.value||'';input.select='summary'}if(/^bindingQuestion/.test(el.name)){const input=Object.values(s.inputs)[Number(el.name.slice(15))];input.select='summary'}if(el.name==='fromStage')s.from.question=questionOptions(p,s.from.stage)[0]?.value||'';if(/^inputStage/.test(el.name)){const input=s.inputs[Number(el.name.slice(10))];input.question=questionOptions(p,input.stage)[0]?.value||''}if(el.dataset.condField==='stage'){const node=conditionAt(s,el.closest('[data-cond-path]').dataset.condPath);node.question=questionOptions(p,node.stage)[0]?.value||''}render()}}catch(error){fail(error)}});
